function safe(v){return String(v==null?"":v);}
function uiMsg(s,bad){var el=byId("ma-message");if(el){el.textContent=s;el.style.color=bad?"#b42318":"#08716d";}}
function optionList(el,arr,placeholder,current){
 if(!el)return;el.replaceChildren();
 var empty=document.createElement("option");empty.value="";empty.textContent=placeholder;el.appendChild(empty);
 arr.forEach(function(it){var o=document.createElement("option");o.value=safe(Array.isArray(it)?it[0]:it);o.textContent=safe(Array.isArray(it)?it[1]:it);el.appendChild(o);});
 if(current&&[...el.options].some(function(o){return o.value===current;}))el.value=current;
}
function initialHijri(){
 try{
  var f=new Intl.DateTimeFormat("en-US-u-ca-islamic-umalqura",{timeZone:"Asia/Riyadh",year:"numeric",month:"numeric",day:"numeric"});
  var p=Object.fromEntries(f.formatToParts(new Date()).filter(function(x){return x.type!=="literal";}).map(function(x){return [x.type,x.value];}));
  return {d:p.day,m:p.month,y:p.year};
 }catch(e){return {d:"",m:"",y:"1448"};}
}
function initialWeekday(){
 try{return new Intl.DateTimeFormat("ar-SA",{timeZone:"Asia/Riyadh",weekday:"long"}).format(new Date()).replace("الاثنين","الإثنين");}catch(e){return "";}
}
